"use client"

import { useState, useEffect } from "react"
import { useDictionary } from "@/components/dictionary-provider"
import { createClient } from "@/lib/supabase"
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { Plus, Building2, Search } from "lucide-react"
import { Input } from "@/components/ui/input"

import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle, 
  DialogTrigger,
  DialogFooter
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { 
  Select, 
  SelectContent, 
  SelectItem, 
  SelectTrigger, 
  SelectValue 
} from "@/components/ui/select"
import { Save, X } from "lucide-react"

export default function CompaniesPage() {
  const { dict } = useDictionary()
  const supabase = createClient()
  const [companies, setCompanies] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [isOpen, setIsOpen] = useState(false)
  const [editingCompany, setEditingCompany] = useState<any>(null)
  
  const [formData, setFormData] = useState({
    name: "",
    type: "Customer"
  })

  async function fetchCompanies() {
    setLoading(true)
    const { data, error } = await supabase.from("companies").select("*").order('created_at', { ascending: false })
    if (!error && data) setCompanies(data)
    setLoading(false)
  }

  useEffect(() => {
    fetchCompanies()
  }, [])

  const handleOpenDialog = (company: any = null) => {
    if (company) {
      setEditingCompany(company)
      setFormData({ name: company.name, type: company.type })
    } else {
      setEditingCompany(null)
      setFormData({ name: "", type: "Customer" })
    }
    setIsOpen(true)
  }

  const handleSubmit = async (e: React.SyntheticEvent<HTMLFormElement, SubmitEvent>) => {
    e.preventDefault()
    const payload = { ...formData }
    
    if (editingCompany) {
      const { error } = await supabase.from("companies").update(payload).eq("id", editingCompany.id)
      if (!error) setIsOpen(false)
    } else {
      const { error } = await supabase.from("companies").insert([payload])
      if (!error) setIsOpen(false)
    }
    fetchCompanies()
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <h1 className="page-title">{dict.TITLE_COMPANIES}</h1>
        
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
          <DialogTrigger asChild>
            <Button className="interactive-click interactive-focus" onClick={() => handleOpenDialog()}>
              <Plus data-icon="inline-start" />
              {dict.TITLE_ADD_COMPANY}
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-[425px]">
            <DialogHeader>
              <DialogTitle>
                {editingCompany ? dict.TITLE_EDIT_COMPANY : dict.TITLE_ADD_COMPANY}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="flex flex-col gap-4 py-4">
              <div className="flex flex-col gap-2">
                <Label htmlFor="name">{dict.LABEL_COMPANY_NAME}</Label>
                <Input 
                  id="name" 
                  value={formData.name} 
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="Acme Corp"
                  className="interactive-focus"
                  required
                />
              </div>
              <div className="flex flex-col gap-2">
                <Label htmlFor="type">{dict.LABEL_TYPE}</Label>
                <Select 
                  value={formData.type} 
                  onValueChange={(value) => setFormData({ ...formData, type: value })}
                >
                  <SelectTrigger className="interactive-focus">
                    <SelectValue placeholder={dict.SEARCH_PLACEHOLDER} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Customer">Customer</SelectItem>
                    <SelectItem value="Supplier">Supplier</SelectItem>
                    <SelectItem value="Transporter">Transporter</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <DialogFooter className="mt-4">
                <Button type="button" variant="outline" onClick={() => setIsOpen(false)} className="interactive-click">
                  <X data-icon="inline-start" />
                  {dict.BUTTON_CANCEL}
                </Button>
                <Button type="submit" className="interactive-click">
                  <Save data-icon="inline-start" />
                  {dict.BUTTON_SAVE}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      <div className="action-bar">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-2.5 top-2.5 size-4 text-muted-foreground" />
          <Input 
            placeholder={dict.SEARCH_PLACEHOLDER} 
            className="pl-8 interactive-focus"
          />
        </div>
      </div>

      <Card className="data-card">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead><Building2 className="size-4 mr-2 inline-block" />{dict.LABEL_NAME}</TableHead>
              <TableHead>{dict.LABEL_TYPE}</TableHead>
              <TableHead className="text-right">{dict.LABEL_ACTIONS}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={3} className="text-center py-8">{dict.LOADING}</TableCell></TableRow>
            ) : companies.length === 0 ? (
              <TableRow><TableCell colSpan={3} className="text-center py-8">{dict.NO_DATA}</TableCell></TableRow>
            ) : (
              companies.map((company) => (
                <TableRow key={company.id} className="interactive-focus group">
                  <TableCell className="font-medium">{company.name}</TableCell>
                  <TableCell>
                    <span className="px-2 py-1 rounded-full text-xs font-semibold bg-secondary">
                      {company.type}
                    </span>
                  </TableCell>
                  <TableCell className="text-right">
                    <Button 
                      variant="ghost" 
                      size="sm" 
                      className="interactive-click"
                      onClick={() => handleOpenDialog(company)}
                    >
                      {dict.BUTTON_EDIT}
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Card>
    </div>
  )
}